import { useEffect, useState } from "react";
import axios from "axios";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

function Dashboard() {

  const [queues, setQueues] = useState([]);

  const [form, setForm] = useState({
    patientName: "",
    doctor: "",
    department: "",
    date: ""
  });

  // FETCH QUEUE
  const fetchQueues = async () => {
    try {
      const res = await axios.get("http://localhost:5000/api/queue/all");
      setQueues(res.data);
    } catch (err) {
      console.log(err);
    }
  };

  // LOAD + SOCKET LISTENERS
  useEffect(() => {
    fetchQueues();

    // REAL-TIME UPDATES
    socket.on("queueUpdated", () => {
      fetchQueues();
    });

    socket.on("queueDeleted", () => {
      fetchQueues();
    });

    socket.on("notification", (msg) => {
      alert(msg);
    });

    return () => {
      socket.off("queueUpdated");
      socket.off("queueDeleted");
      socket.off("notification");
    };
  }, []);

  // BOOK OP
  const bookOP = async () => {
    try {
      await axios.post("http://localhost:5000/api/queue/add", form);

      setForm({
        patientName: "",
        doctor: "",
        department: "",
        date: ""
      });

      alert("OP Booked Successfully");

    } catch (err) {
      alert("Booking Failed");
    }
  };

  // CONFIRM OP
  const confirmOP = async (id) => {
    try {
      await axios.put(`http://localhost:5000/api/queue/confirm/${id}`);
    } catch (err) {
      console.log(err);
    }
  };

  // JOIN QUEUE
  const joinQueue = async (id) => {
    try {
      await axios.put(`http://localhost:5000/api/queue/join/${id}`);
    } catch (err) {
      alert(err.response?.data || "Join Failed");
    }
  };

  // COMPLETE OP
  const completeOP = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/api/queue/complete/${id}`);
    } catch (err) {
      console.log(err);
    }
  };

  return (
    <div style={{ padding: "30px" }}>

      <h1>🏥 Hospital OP Queue System</h1>

      {/* FORM */}
      <div style={{ marginBottom: "20px" }}>

        <input
          placeholder="Patient Name"
          value={form.patientName}
          onChange={(e) => setForm({ ...form, patientName: e.target.value })}
        />

        <input
          placeholder="Doctor"
          value={form.doctor}
          onChange={(e) => setForm({ ...form, doctor: e.target.value })}
        />

        <input
          placeholder="Department"
          value={form.department}
          onChange={(e) => setForm({ ...form, department: e.target.value })}
        />

        <input
          type="date"
          value={form.date}
          onChange={(e) => setForm({ ...form, date: e.target.value })}
        />

        <button onClick={bookOP}>Book OP</button>
      </div>

      {/* LIST */}
      {queues.length === 0 ? (
        <p>No Queue Data</p>
      ) : (
        queues.map((q) => (
          <div
            key={q._id}
            style={{
              border: "1px solid black",
              padding: "10px",
              marginBottom: "10px",
              background:
                q.status === "Waiting"
                  ? "#fff3cd"
                  : q.status === "Confirmed"
                  ? "#cce5ff"
                  : q.status === "InQueue"
                  ? "#d4edda"
                  : "#f8d7da"
            }}
          >

            <h3>Token: {q.tokenNumber}</h3>
            <p>Patient: {q.patientName}</p>
            <p>Status: <b>{q.status}</b></p>

            <button onClick={() => confirmOP(q._id)}>
              Confirm
            </button>

            <button onClick={() => joinQueue(q._id)}>
              Join Queue
            </button>

            <button onClick={() => completeOP(q._id)}>
              Complete
            </button>

          </div>
        ))
      )}

    </div>
  );
}

export default Dashboard;
